    public function update_transaction($tid)
    {
        $result = $this->transactions_model->get_transaction_by_id($tid);

        if (is_array($result) && !empty($result) && count($result) > 0) {
            if (isset($_POST) && is_array($_POST) && !empty($_POST)) {
                $user_email = $this->input->post('user');
                $id  = $this->transactions_model->get_user_id($user_email);

                if (is_array($id) && !empty($id)) {
                    $data['order_id'] = $this->input->post('order_id');
                    $data['purchase_id'] = $this->input->post('purchase_id');
                    $data['amount'] = $this->input->post('total_cost');
                    $data['pay_out'] = $this->input->post('pay_out');
                    $data['transaction_date'] = $this->input->post('transaction_date');
                    $data['created_by'] = $_SESSION['user_id'];
                    $data['user'] = $id[0]['id'];
                    $update_result = $this->transactions_model->update_transaction($tid, $data);

                    if ($update_result == true) {
                        $data['success_response'] = 'transaction Updated successfully';
                    } else {
                        $data['error_response'] = 'Failed to Update Transaction';
                    }
                } else {
                    $data['error_response'] = 'User email not found';
                }
            }

            $data['tid'] = $tid;
            $data['transaction_data'] = $result;
            $data['_view'] = 'transaction/update';
            $this->load->view('layouts/main', $data);
        } else {
            redirect('');
            return false;
        }
    }

    public function delete_transaction($id)
    {
        $this->transactions_model->delete_transaction($id);
        redirect('');
        return true;
    }
}
